---SetCharacterInfo
---设置 角色信息
function BattleStatisticCharacterNode:SetCharacterInfo(roleData)
    local roleData = checkTable(roleData)
    local skinId = checkNumber(roleData.cardSkin) -- 皮肤Id
    local cardId = checkNumber(roleData.cardId) -- 卡牌Id
    local cardSkinVo = CardConfMgr:GetCardSkinBySkinId(skinId)
    local stars = checkNumber(roleData.star)-- 人物星级
    local characterLv = checkNumber(roleData.cardLevel) -- 角色等级
    local characterData = CardConfMgr:GetInstance():GetCardByRefId(cardId)
    local strCharacterLv
    --- 人物头像
    self.CardHead:LoadSprite(cardSkinVo.cardHeadList)
    --- 人物名称
    local cardName = cardSkinVo.name
    cardName = string.isEmpty(cardName) and localize("战斗员") or cardName
    self.TxtCardName.text = cardName
    --- 人物品级 颜色
    local cardRare = checkNumber(characterData.rare)
    local cardComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
    local cardDojo = roleData
    local advanceLevel = cardDojo and checkNumber(cardDojo.advanceLevel) or 0
    if advanceLevel > 0 then
        cardRare = CardConfMgr:GetInstance():GetCardRare(advanceLevel, characterData.rare)
    end

    if not IsNull(self.ImgRoleBGRare) then
        self.ImgRoleBGRare.Status = cardRare
    end
    if not IsNull(self.ImgRoleSignRare) then
        self.ImgRoleSignRare.Status = cardRare
    end
    local attributeIconPath = CardUtils.GetGoodsCardAttrIconByCardAttrType(characterData.attributeType)
    if attributeIconPath then
        self.Element:LoadSprite(attributeIconPath)
    end
    local careerType = checkNumber(characterData.career)
    self.ImgCareer:LoadSprite(UIBattlingTools.GetCareerIconCommon(careerType, true))
    if not IsNull(stars) then
        -- local starVo = CardConfMgr:GetInstance():GetCardStarInfo(cardId, stars)
        -- local maxLevel = checkNumber(starVo.maxLevel)
        -- if characterLv >= maxLevel and stars >= 6 then
        --     strCharacterLv = "MAX"
        -- else
            strCharacterLv = characterLv > 0 and characterLv <= 9
                    and string.format("0%d", characterLv)
                    or checkString(characterLv)
        -- end
    end
    if (not IsNull(self.LvLabel)) and strCharacterLv then
        self.LvLabel.text = strCharacterLv
    end
end

---SetCharacterBattleInfo
---设置 人物战斗信息
---@param dataServer table
---@param dataTotal table
function BattleStatisticCharacterNode:SetCharacterBattleInfo(dataServer, dataTotal)
    xTry(function()
        local damage = self:GetValue(dataServer.damage)
        local damagePre = damage > 0 and (damage / dataTotal.damage) or 0
        local bear = self:GetValue(dataServer.bear)
        local bearPre = bear > 0 and (bear / dataTotal.bear) or 0
        local skillCard = self:GetValue(dataServer.skillCard)
        local cure = self:GetValue(dataServer.cure)
        local curePre = cure > 0 and (cure / dataTotal.cure) or 0
        self.TxtDamageNum.text = tostring(damage)
        self.DamageProgress.value = damagePre
        self.TxtGetDamage.text = tostring(bear)
        self.GetDamageProgress.value = bearPre
        self.TxtHeallingNum.text = tostring(cure)
        self.HeallingProgress.value = curePre
        self.TxtCardUsed.text = string.format("x%d", skillCard)
    end)
end

---GetValue
---获取绝对&&向上取整值
---@param value number
function BattleStatisticCharacterNode:GetValue(value)
    return checkNumber(math.floor(math.abs(value)))
end

return BattleStatisticCharacterNode
